"""Regenerate fixed Twofish vectors using libgcrypt (not the vault backend).
Run from any directory; normal C tests do not require libgcrypt or Python.
"""
import ctypes as c
from pathlib import Path

lib = c.CDLL('libgcrypt.so.20')
lib.gcry_check_version.argtypes = [c.c_char_p]
lib.gcry_check_version.restype = c.c_char_p
lib.gcry_cipher_open.argtypes = [c.POINTER(c.c_void_p), c.c_int, c.c_int, c.c_uint]
lib.gcry_cipher_setkey.argtypes = [c.c_void_p, c.c_void_p, c.c_size_t]
lib.gcry_cipher_encrypt.argtypes = [c.c_void_p, c.c_void_p, c.c_size_t, c.c_void_p, c.c_size_t]
lib.gcry_cipher_close.argtypes = [c.c_void_p]
lib.gcry_cipher_close.restype = None
assert lib.gcry_check_version(None)

def encrypt(key, block):
    handle = c.c_void_p()
    assert lib.gcry_cipher_open(c.byref(handle), 10, 1, 0) == 0  # TWOFISH, ECB
    try:
        assert lib.gcry_cipher_setkey(handle, key, len(key)) == 0
        out = c.create_string_buffer(len(block))
        assert lib.gcry_cipher_encrypt(handle, out, len(block), block, len(block)) == 0
        return out.raw
    finally:
        lib.gcry_cipher_close(handle)

def xts(key, lba, data):
    tweak = int.from_bytes(encrypt(key[32:], lba.to_bytes(16, 'little')), 'little')
    out = b''
    for i in range(0, len(data), 16):
        block = int.from_bytes(data[i:i+16], 'little') ^ tweak
        out += (int.from_bytes(encrypt(key[:32], block.to_bytes(16, 'little')), 'little') ^ tweak).to_bytes(16, 'little')
        tweak = ((tweak << 1) & ((1 << 128)-1)) ^ (0x87 if tweak >> 127 else 0)
    return out

def wrap(key, data):
    a = bytes([0xa6])*8
    blocks = [data[i:i+8] for i in range(0, len(data), 8)]
    for j in range(6):
        for i in range(4):
            b = encrypt(key, a + blocks[i])
            a = (int.from_bytes(b[:8], 'big') ^ (4*j+i+1)).to_bytes(8, 'big')
            blocks[i] = b[8:]
    return a + b''.join(blocks)

key = bytes.fromhex('0123456789abcdeffedcba987654321000112233445566778899aabbccddeeff')
assert encrypt(key, bytes(16)).hex() == '37527be0052334b89f0cfccae87cfa20'
values = {'tf_kat_key': key, 'tf_kat_cipher': encrypt(key, bytes(16)),
          'tf_wrap_key': bytes(range(32)), 'tf_share': bytes(range(32,64)),
          'tf_wrapped': wrap(bytes(range(32)), bytes(range(32,64)))}
for i, lba in enumerate([0, 0x123456789abcdef0, (1<<64)-1]):
    k = bytes((j+71*i)&255 for j in range(64))
    plain = bytes((j*13+7+i)&255 for j in range(512))
    values.update({f'tf_xts_key_{i}': k, f'tf_plain_{i}': plain, f'tf_cipher_{i}': xts(k,lba,plain)})
out = '/* Generated by generate_twofish.py using libgcrypt Twofish ECB. */\n'
for name, data in values.items():
    out += f'static const uint8_t {name}[{len(data)}] = {{\n'
    out += ''.join('    '+','.join(f'0x{x:02x}' for x in data[i:i+16])+',\n' for i in range(0,len(data),16)) + '};\n'
Path(__file__).with_name('twofish_vectors.h').write_text(out)
